import pickle
import sys

def load_filters(filter_file):
    """Load filter configuration from file."""
    with open(filter_file, 'rb') as f:
        return pickle.load(f)

def parse_log_line(line):
    """Parse a single log line in pipe-delimited format."""
    parts = line.strip().split('|')
    if len(parts) >= 3:
        return {
            'timestamp': parts[0],
            'level': parts[1],
            'message': parts[2]
        }
    return None

def process_logs(log_file, filters):
    """Filter and process log entries."""
    results = []
    with open(log_file, 'r') as f:
        for line in f:
            entry = parse_log_line(line)
            if entry and entry['level'] in filters['levels']:
                results.append(entry)
    return results

if __name__ == '__main__':
    if len(sys.argv) < 3:
        print('Usage: python log_parser.py <log_file> <filter_config>')
        sys.exit(1)

    log_file = sys.argv[1]
    filter_config = sys.argv[2]

    # Load filter configuration
    filters = load_filters(filter_config)

    # Process logs
    matched = process_logs(log_file, filters)

    for entry in matched:
        print(f"{entry['timestamp']} [{entry['level']}] {entry['message']}")
